S3 = '33333333-aaaa-4bbb-8ccc-000000000003'  # beta, chinese
S4 = '44444444-aaaa-4bbb-8ccc-000000000004'  # alpha, history only (transcript deleted)
S5 = '55555555-aaaa-4bbb-8ccc-000000000005'  # alpha, no prompt at all
S6 = '66666666-aaaa-4bbb-8ccc-000000000006'  # gamma, project only known from history

ALPHA = '/Users/me/Code/alpha'
BETA = '/Users/me/Code/beta'
GAMMA = '/Users/me/Code/gamma'


def enc(path: str) -> str:
    import re

    return re.sub(r'[^A-Za-z0-9-]', '-', path)


def ms(iso: str) -> int:
    return int(datetime.fromisoformat(iso.replace('Z', '+00:00')).timestamp() * 1000)


_uuid_n = 0


def uid() -> str:
    global _uuid_n
    _uuid_n += 1
    return f'{_uuid_n:08x}-0000-4000-8000-{_uuid_n:012x}'


def env(sid, ts, cwd, branch='main', parent=None, **extra):
    d = {
        'parentUuid': parent,
        'isSidechain': False,
        'userType': 'external',
        'entrypoint': 'cli',
        'cwd': cwd,
        'sessionId': sid,
        'version': '2.1.260',
        'gitBranch': branch,
        'uuid': uid(),
        'timestamp': ts,
    }
    d.update(extra)
    return d


def user(sid, ts, content, cwd=ALPHA, **extra):
    d = env(sid, ts, cwd, **extra)
    d.update({'type': 'user', 'message': {'role': 'user', 'content': content}})
    return d


def assistant(sid, ts, blocks, cwd=ALPHA, model='claude-opus-5', branch='main', usage=None):
    d = env(sid, ts, cwd, branch=branch)
    d['requestId'] = 'req_' + uid()[:8]
    d['message'] = {
        'model': model,
        'id': 'msg_' + uid()[:8],
        'type': 'message',
        'role': 'assistant',
        'content': blocks,
        'stop_reason': 'end_turn',
        'usage': usage or {'input_tokens': 10, 'output_tokens': 20},
    }
    # Real files put `message` before the top-level `type`, so byte prefilters must not rely on
    # the first "type" key being the record type.
    d['type'] = 'assistant'
    return d


def tool_result(sid, ts, tool_use_id, content, cwd=ALPHA):
    d = user(sid, ts, [{'tool_use_id': tool_use_id, 'type': 'tool_result', 'content': content}], cwd=cwd)
    d['toolUseResult'] = {'stdout': content if isinstance(content, str) else '', 'stderr': ''}
    return d


def dumps(o) -> str:
    return json.dumps(o, ensure_ascii=False, separators=(',', ':'))


def write_jsonl(path: Path, records):
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, 'w', encoding='utf-8') as fp:
        for r in records:
            fp.write(r if isinstance(r, str) else dumps(r))
            fp.write('\n')


