def main():
    if OUT.exists():
        shutil.rmtree(OUT)
    projects = OUT / 'projects'
    alpha, beta = projects / enc(ALPHA), projects / enc(BETA)
    write_jsonl(alpha / f'{S1}.jsonl', session_1())
    write_jsonl(alpha / S1 / 'subagents' / 'agent-a1b2c3.jsonl', session_1_subagent())
    (alpha / S1 / 'subagents' / 'agent-a1b2c3.meta.json').write_text(
        dumps({'agentType': 'Explore', 'description': 'Explore the repo', 'toolUseId': 'toolu_x', 'spawnDepth': 1})
    )
    write_jsonl(alpha / f'{S2}.jsonl', session_2())
    write_jsonl(alpha / f'{S5}.jsonl', session_5())
    write_jsonl(beta / f'{S3}.jsonl', session_3())
    (alpha / 'memory').mkdir()
    (alpha / 'memory' / 'MEMORY.md').write_text('- not a transcript\n')
    (alpha / 'notes.txt').write_text('not a transcript either\n')
    write_jsonl(OUT / 'history.jsonl', history_rows())
    (OUT / 'paste-cache').mkdir()
    (OUT / 'paste-cache' / 'deadbeef01234567.txt').write_text('cached paste')
    print(f'wrote {OUT}')


if __name__ == '__main__':
    main()
